package com.past9.phoneaos.system

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager

/**
 * The user's character IS the app: its launcher icon and notification glyph follow the mascot
 * and colour they picked. Icons are activity-aliases generated by IconGen (one per mascot x colour).
 */
object Identity {
    fun statIcon(context: Context, mascot: String): Int =
        context.resources.getIdentifier("ic_stat_$mascot", "drawable", context.packageName).takeIf { it != 0 } ?: com.past9.phoneaos.R.drawable.ic_stat_agent

    /** Switch the home-screen icon. Call when the app goes to the background, never mid-use. */
    fun applyLauncherIcon(context: Context, mascot: String, accent: String) {
        val pm = context.packageManager
        val want = ComponentName(context, "${context.packageName}.Icon_${mascot}_$accent")
        val enabled = runCatching { pm.getComponentEnabledSetting(want) }.getOrNull() ?: return
        if (enabled == PackageManager.COMPONENT_ENABLED_STATE_ENABLED) return
        val aliases = pm.getPackageInfo(context.packageName, PackageManager.GET_ACTIVITIES or PackageManager.MATCH_DISABLED_COMPONENTS).activities.orEmpty()
            .map { it.name }.filter { it.contains(".Icon_") }
        if (want.className !in aliases) return
        pm.setComponentEnabledSetting(want, PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP)
        aliases.filter { it != want.className }.forEach {
            pm.setComponentEnabledSetting(ComponentName(context, it), PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP)
        }
    }
}
